import{_ as r,l as o,o as e,c as n,v as l,p,x as t,d as s,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"FlexRay / 可编程光瞳","description":"","frontmatter":{"title":"FlexRay / 可编程光瞳","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/flexray-pupil.md","filePath":"litho/flexray-pupil.md","lastUpdated":1789023840000}'),h={name:"litho/flexray-pupil.md"};function u(A,a,x,c,m,D){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="flexray-可编程光瞳" tabindex="-1">FlexRay / 可编程光瞳 <a class="header-anchor" href="#flexray-可编程光瞳" aria-label="Permalink to &quot;FlexRay / 可编程光瞳&quot;">​</a></h1><div class="epigraph"><p>固定衍射元件给出几张经典光瞳；可编程微镜把同一照明器变成可按层改写的瞳面灰度，自由形状仍是离轴照明，不是新波长。</p><footer>—— 据 ASML 对 FlexRay 可编程照明器的公开产品与 SPIE 论述整理</footer></div><p><a href="/litho/annular-dipole-quad">上一课</a>把环形、偶极、四极钉成一组离散瞳形。缺口是：逻辑金属、切线、孔、SRAM 要的节距窗口互不相同，DOE 换片既慢又不连续，SMO 画出来的花瓣也落不进固定孔径。本课钉 ASML FlexRay 一类的可编程光瞳：自由光瞳对固定孔径。照明偏振留给<a href="/litho/illuminator-polarization">下一课</a>，不在这里开始转琼斯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典 OAI 的交付物是「选一张 DOE」。换层要换元件、要重新标定内外 \\(\\sigma\\) 与极张角，档位之间没有中间形状。二维层的工艺窗交往往落在「不像偶极、也不像标准 C-quad」的区域：能量要在瞳面上按像素分配。固定孔径给不出这种分配。</p><p>缺口因此是照明器能不能按曝光配方改写瞳面，而不是再比较环形和偶极谁更一维。没有可编程瞳，后课的偏振控制只能加在那几张固定图上，SMO 也只能停在纸面。</p><h3 id="自由光瞳仍受-etendue-约束" tabindex="-1">自由光瞳仍受 etendue 约束 <a class="header-anchor" href="#自由光瞳仍受-etendue-约束" aria-label="Permalink to &quot;自由光瞳仍受 etendue 约束&quot;">​</a></h3><p>微镜可以关掉瞳面上的一块，不能把准分子的étendue 变大。总功率有上限；把能量挤进很小的极，晶圆面剂量时间变长，与上一课偶极挡光是同一类账。FlexRay 的「自由」是形状自由，不是亮度无限。</p><p><span class="marginnote">ASML FlexRay 用照明光路里的微镜阵列合成瞳面；公开叙事把它写成可在配方间切换、并支持自由形状照明，以替代或补充 DOE 换片。不要把汽车总线同名协议和扫描机照明器混成一个词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传统路径：环形 / 偶极 / C-quad 做在 DOE 或光阑上，机械切换。FlexRay 路径：微镜把源成像到瞳面像素，灰度（或开关）逼近目标光瞳，再经中继进掩模。同一硬件可以生成上一课的全部经典形状，也可以生成 SMO 输出的非对称花瓣。切换时间按配方，不必为每一种金属节距准备一张玻璃。</p><p>工程约束仍然在：最小可点亮斑、热负载、偏振纯度、以及两台机器之间的光瞳匹配。自由光瞳的匹配误差会变成 CD 与套刻指纹，比「都用同一张 DOE」更需要机台间校准。</p><h3 id="与-smo-的接口" tabindex="-1">与 SMO 的接口 <a class="header-anchor" href="#与-smo-的接口" aria-label="Permalink to &quot;与 SMO 的接口&quot;">​</a></h3><p><a href="/litho/smo">SMO</a> 在像素化瞳面上搜，输出必须投影到照明器可实现集合。FlexRay 把这个集合从「四五张 DOE」扩成一块可编程灰度。本课不跑 SMO 目标函数，只要求：计算光刻给出的光瞳，若不能被微镜实现，就只是图。冻结光瞳之后，全芯片 OPC 仍按该瞳重做，与换 DOE 同一纪律。</p>',14)),(e(),p(d,null,{default:t(()=>[E(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOE%5B%22DOE%20%2F%20%E5%9B%BA%E5%AE%9A%E5%AD%94%E5%BE%84%22%5D%20--%3E%20DISC%5B%22%E7%8E%AF%E5%BD%A2%E5%81%B6%E6%9E%81%E5%9B%9B%E6%9E%81%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20FR%5B%22FlexRay%20%E5%BE%AE%E9%95%9C%22%5D%20--%3E%20FREE%5B%22%E5%8F%AF%E7%BC%96%E7%A8%8B%E7%9E%B3%E9%9D%A2%E7%81%B0%E5%BA%A6%22%5D%0A%20%20DISC%20--%3E%20CLASS%5B%22%E7%BB%8F%E5%85%B8%20OAI%22%5D%0A%20%20FREE%20--%3E%20CLASS%0A%20%20FREE%20--%3E%20SMO%5B%22SMO%20%E8%8A%B1%E7%93%A3%E5%8F%AF%E8%90%BD%E5%9C%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Hopkins 的 TCC 由光源支撑决定。改微镜开关就是改支撑，从而改哪些衍射级对能贡献调制。经典偶极是支撑的两个小岛；自由光瞳可以是许多小岛或一段弯环，用来同时照顾几类关键 clips。能量效率来自「亮着的镜子」占照明光瞳的比例，以及中继损耗。</p><p>层间不要共用一张自由光瞳。栅极的花瓣对切线层常常是灾难：切线要的是稀疏图形的焦深，不是最密栅的两束。配方按层绑定瞳图，与绑定剂量、焦距同一级别。</p><p>DOE 并没有被物理上废除：有的机台仍用经典元件当种子或备份，FlexRay 再微调。本课对比的是「可改写」对「换玻璃」，不是宣布工厂里已经没有环形 DOE。</p><p><span class="marginnote">可编程不等于每场都改光瞳。一场曝光里瞳面通常冻结；变的是层与层之间。把 FlexRay 理解成像素级实时扫描光源，是把照明器和工件台扫描混为一谈。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 EUV 照明器：NXE 的照明与 FlexRay 不是同一模块，斜入射与反射瞳另论。也不把微镜的镜面相位写进掩模 3D。产能数字只承认定性：填充越瘦，剂量时间越长；不要把某代 NXT 的 wph 乘进本课。</p><p>后课默认：说到「这层的照明」，可以是经典环形/偶极，也可以是 FlexRay 自由瞳；两者都是 OAI，都必须声明形状。偏振是附加在这张瞳上的矢量场，下一课才加。</p><p><span class="marginnote">两台带 FlexRay 的扫描机，微镜标定残差会表现为光瞳指纹差。单机匹配要把自由瞳纳入，不能只对一套 C-quad DOE 做匹配。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固定 DOE 给出离散 OAI；FlexRay 用微镜写瞳面灰度。</li><li>自由光瞳让 SMO 的花瓣可上机，仍受 etendue 与热约束。</li><li>形状自由不是功率自由；瘦瞳会吃扫描时间。</li><li>光瞳按层冻结，一场内不当成实时扫描源。</li><li>下一课在瞳形上加偏振。</li><li>出处：ASML FlexRay 可编程照明器公开材料；上一课 Mack / ASML 对经典瞳形的分类。</li></ul>',11))])}const f=r(h,[["render",u]]);export{_ as __pageData,f as default};
